import * as dotenv from "dotenv";
import * as fs from "fs";
import * as path from "path";
import { Connection, Keypair, clusterApiUrl, Commitment } from "@solana/web3.js";

// Load .env from project root
dotenv.config({ path: path.resolve(__dirname, "..", ".env") });

/**
 * Typed configuration object derived from environment variables.
 */
export interface Config {
  adminKeypairPath: string;
  solanaCluster: string;
  tokenDecimals: number;
  totalSupply: number;
  revokeMintAuthority: boolean;
  saleAllocation: number;
  priceLamportsPerWholeToken: number;
  perWalletMaxTokens: number;
  saleDurationSeconds: number;
  treasuryPubkey: string;
  mintAddress: string;
}

/**
 * Reads and returns all configuration values from environment variables.
 * Throws if required variables are missing or invalid.
 */
export function getConfig(): Config {
  const adminKeypairPath = process.env.ADMIN_KEYPAIR_PATH || "~/.config/solana/id.json";
  const solanaCluster = process.env.SOLANA_CLUSTER || "devnet";
  const tokenDecimals = parseInt(process.env.TOKEN_DECIMALS || "9", 10);
  const totalSupply = parseInt(process.env.TOTAL_SUPPLY || "1000000", 10);
  const revokeMintAuthority = (process.env.REVOKE_MINT_AUTHORITY || "true").toLowerCase() === "true";
  const saleAllocation = parseInt(process.env.SALE_ALLOCATION || "500000", 10);
  const priceLamportsPerWholeToken = parseInt(process.env.PRICE_LAMPORTS_PER_WHOLE_TOKEN || "1000000", 10);
  const perWalletMaxTokens = parseInt(process.env.PER_WALLET_MAX_TOKENS || "10000", 10);
  const saleDurationSeconds = parseInt(process.env.SALE_DURATION_SECONDS || "86400", 10);
  const treasuryPubkey = process.env.TREASURY_PUBKEY || "";
  const mintAddress = process.env.MINT_ADDRESS || "";

  if (isNaN(tokenDecimals) || tokenDecimals < 0 || tokenDecimals > 18) {
    throw new Error(`Invalid TOKEN_DECIMALS: ${process.env.TOKEN_DECIMALS}`);
  }
  if (isNaN(totalSupply) || totalSupply <= 0) {
    throw new Error(`Invalid TOTAL_SUPPLY: ${process.env.TOTAL_SUPPLY}`);
  }

  return {
    adminKeypairPath,
    solanaCluster,
    tokenDecimals,
    totalSupply,
    revokeMintAuthority,
    saleAllocation,
    priceLamportsPerWholeToken,
    perWalletMaxTokens,
    saleDurationSeconds,
    treasuryPubkey,
    mintAddress,
  };
}

/**
 * Resolves a file path, expanding the `~` home directory shorthand.
 */
function resolvePath(filePath: string): string {
  if (filePath.startsWith("~")) {
    const home = process.env.HOME || process.env.USERPROFILE || "";
    return path.join(home, filePath.slice(1));
  }
  return path.resolve(filePath);
}

/**
 * Loads a Solana Keypair from a JSON file on disk.
 * The file should contain a JSON array of 64 bytes (secret key).
 *
 * @param keypairPath - Path to the keypair JSON file
 * @returns The loaded Keypair
 */
export function loadKeypair(keypairPath: string): Keypair {
  const resolved = resolvePath(keypairPath);
  if (!fs.existsSync(resolved)) {
    throw new Error(`Keypair file not found: ${resolved}`);
  }
  const raw = fs.readFileSync(resolved, "utf-8");
  const secretKey = Uint8Array.from(JSON.parse(raw));
  return Keypair.fromSecretKey(secretKey);
}

/**
 * Creates and returns a Solana Connection to the configured cluster.
 * Supports "devnet", "testnet", "mainnet-beta", and "localhost".
 *
 * @returns A Connection instance
 */
export function getConnection(): Connection {
  const config = getConfig();
  const cluster = config.solanaCluster;

  let endpoint: string;
  if (cluster === "localhost" || cluster === "localnet") {
    endpoint = "http://127.0.0.1:8899";
  } else if (cluster === "devnet" || cluster === "testnet" || cluster === "mainnet-beta") {
    endpoint = clusterApiUrl(cluster);
  } else {
    // Treat as custom RPC URL
    endpoint = cluster;
  }

  console.log(`🔗 Connecting to Solana cluster: ${cluster} (${endpoint})`);
  return new Connection(endpoint, "confirmed");
}

/**
 * Confirms a transaction on-chain with the specified commitment level.
 * Throws if the transaction fails or times out.
 *
 * @param connection - Solana RPC connection
 * @param signature - Transaction signature to confirm
 * @param commitment - Commitment level (default: "confirmed")
 */
export async function confirmTx(
  connection: Connection,
  signature: string,
  commitment: Commitment = "confirmed"
): Promise<void> {
  console.log(`⏳ Confirming transaction: ${signature}`);

  const latestBlockhash = await connection.getLatestBlockhash(commitment);
  const confirmation = await connection.confirmTransaction(
    {
      signature,
      blockhash: latestBlockhash.blockhash,
      lastValidBlockHeight: latestBlockhash.lastValidBlockHeight,
    },
    commitment
  );

  if (confirmation.value.err) {
    throw new Error(`Transaction failed: ${JSON.stringify(confirmation.value.err)}`);
  }

  console.log(`✅ Transaction confirmed: ${signature}`);
}

/**
 * Converts a whole-token amount to base units (lamports equivalent for the token).
 *
 * @param wholeTokens - Number of whole tokens
 * @param decimals - Token decimal places
 * @returns The amount in base units as a bigint-compatible number
 */
export function toBaseUnits(wholeTokens: number, decimals: number): bigint {
  return BigInt(wholeTokens) * BigInt(10 ** decimals);
}

/**
 * Formats a base-unit amount back to a human-readable whole-token string.
 *
 * @param baseUnits - Amount in base units
 * @param decimals - Token decimal places
 * @returns Formatted string
 */
export function fromBaseUnits(baseUnits: bigint | number, decimals: number): string {
  const divisor = BigInt(10 ** decimals);
  const bu = BigInt(baseUnits);
  const whole = bu / divisor;
  const remainder = bu % divisor;
  if (remainder === BigInt(0)) {
    return whole.toString();
  }
  const remainderStr = remainder.toString().padStart(decimals, "0").replace(/0+$/, "");
  return `${whole}.${remainderStr}`;
}

import { PublicKey, Keypair } from "@solana/web3.js";
import {
  createMint,
  getOrCreateAssociatedTokenAccount,
  mintTo,
  setAuthority,
  AuthorityType,
} from "@solana/spl-token";
import { getConfig, loadKeypair, getConnection, toBaseUnits, fromBaseUnits } from "./helpers";

/**
 * create-token.ts
 *
 * Creates a new SPL token mint, mints the total supply to the admin's
 * associated token account, and optionally revokes the mint authority
 * to make the supply permanently fixed.
 *
 * Usage:
 *   npx ts-node scripts/create-token.ts
 *
 * Prerequisites:
 *   - .env file with ADMIN_KEYPAIR_PATH, TOKEN_DECIMALS, TOTAL_SUPPLY,
 *     REVOKE_MINT_AUTHORITY, and SOLANA_CLUSTER configured.
 *   - Admin keypair must have enough SOL for transaction fees.
 */
async function main(): Promise<void> {
  console.log("🚀 Starting token creation...\n");

  // 1. Load configuration
  const config = getConfig();
  const connection = getConnection();

  // 2. Load admin keypair
  console.log(`📂 Loading admin keypair from: ${config.adminKeypairPath}`);
  const admin: Keypair = loadKeypair(config.adminKeypairPath);
  console.log(`👤 Admin public key: ${admin.publicKey.toBase58()}`);

  // Check admin balance
  const balance = await connection.getBalance(admin.publicKey);
  console.log(`💰 Admin balance: ${balance / 1e9} SOL\n`);
  if (balance < 0.01 * 1e9) {
    throw new Error(
      "Admin account has insufficient SOL. Please fund the account first.\n" +
      "  For devnet: solana airdrop 2 " + admin.publicKey.toBase58()
    );
  }

  // 3. Create the mint (no freeze authority)
  console.log(`🏭 Creating mint with ${config.tokenDecimals} decimals...`);
  const mint: PublicKey = await createMint(
    connection,
    admin,                    // payer
    admin.publicKey,          // mint authority
    null,                     // freeze authority (none)
    config.tokenDecimals      // decimals
  );
  console.log(`✅ Mint created: ${mint.toBase58()}\n`);

  // 4. Create the admin's associated token account (ATA)
  console.log("📦 Creating admin's associated token account...");
  const adminAta = await getOrCreateAssociatedTokenAccount(
    connection,
    admin,                    // payer
    mint,                     // mint
    admin.publicKey            // owner
  );
  console.log(`✅ Admin ATA: ${adminAta.address.toBase58()}\n`);

  // 5. Mint the total supply to admin's ATA
  const totalSupplyBaseUnits = toBaseUnits(config.totalSupply, config.tokenDecimals);
  console.log(
    `🪙 Minting ${config.totalSupply} tokens ` +
    `(${totalSupplyBaseUnits.toString()} base units) to admin ATA...`
  );
  const mintTxSig = await mintTo(
    connection,
    admin,                    // payer
    mint,                     // mint
    adminAta.address,         // destination
    admin,                    // mint authority
    totalSupplyBaseUnits      // amount in base units
  );
  console.log(`✅ Mint transaction: ${mintTxSig}\n`);

  // 6. Optionally revoke mint authority
  if (config.revokeMintAuthority) {
    console.log("🔒 Revoking mint authority (supply is now permanently fixed)...");
    const revokeTxSig = await setAuthority(
      connection,
      admin,                  // payer
      mint,                   // account (the mint)
      admin,                  // current authority
      AuthorityType.MintTokens, // authority type
      null                    // new authority (null = revoke)
    );
    console.log(`✅ Mint authority revoked. Tx: ${revokeTxSig}\n`);
  } else {
    console.log("⚠️  Mint authority NOT revoked. Admin can still mint more tokens.\n");
  }

  // 7. Print summary
  console.log("═══════════════════════════════════════════════════════════");
  console.log("  TOKEN CREATION COMPLETE");
  console.log("═══════════════════════════════════════════════════════════");
  console.log(`  Mint Address:      ${mint.toBase58()}`);
  console.log(`  Admin Pubkey:      ${admin.publicKey.toBase58()}`);
  console.log(`  Admin ATA:         ${adminAta.address.toBase58()}`);
  console.log(`  Total Supply:      ${fromBaseUnits(totalSupplyBaseUnits, config.tokenDecimals)} tokens`);
  console.log(`  Decimals:          ${config.tokenDecimals}`);
  console.log(`  Mint Revoked:      ${config.revokeMintAuthority ? "Yes ✅" : "No ⚠️"}`);
  console.log(`  Cluster:           ${config.solanaCluster}`);
  console.log("═══════════════════════════════════════════════════════════");
  console.log("");
  console.log("👉 Next step: Add the following to your .env file:");
  console.log(`   MINT_ADDRESS=${mint.toBase58()}`);
  console.log("");
}

main().catch((err) => {
  console.error("❌ Error creating token:", err);
  process.exit(1);
});

import * as fs from "fs";
import * as path from "path";
import { PublicKey, SystemProgram, Keypair } from "@solana/web3.js";
import { TOKEN_PROGRAM_ID, ASSOCIATED_TOKEN_PROGRAM_ID, getAssociatedTokenAddressSync } from "@solana/spl-token";
import { Program, AnchorProvider, Wallet, BN, Idl } from "@coral-xyz/anchor";
import { getConfig, loadKeypair, getConnection, confirmTx, toBaseUnits, fromBaseUnits } from "./helpers";

/**
 * create-sale.ts
 *
 * Initializes a fixed-price token sale on-chain by calling the
 * `initialize_sale` instruction on the deployed Anchor program.
 *
 * Usage:
 *   npx ts-node scripts/create-sale.ts
 *
 * Prerequisites:
 *   - .env file with MINT_ADDRESS set (from create-token.ts output)
 *   - Anchor program built and deployed
 *   - Admin keypair funded with SOL
 */

/**
 * Loads the Anchor IDL from the built program artifacts.
 * Searches in the standard Anchor build output directory.
 */
function loadIdl(): { idl: Idl; programId: PublicKey } {
  const possiblePaths = [
    path.resolve(__dirname, "..", "target", "idl", "token_sale.json"),
    path.resolve(__dirname, "..", ".anchor", "idl", "token_sale.json"),
  ];

  let idlPath: string | undefined;
  for (const p of possiblePaths) {
    if (fs.existsSync(p)) {
      idlPath = p;
      break;
    }
  }

  if (!idlPath) {
    throw new Error(
      "IDL file not found. Please build the Anchor program first:\n" +
      "  anchor build\n" +
      `Searched paths:\n  ${possiblePaths.join("\n  ")}`
    );
  }

  console.log(`📄 Loading IDL from: ${idlPath}`);
  const idlRaw = JSON.parse(fs.readFileSync(idlPath, "utf-8"));

  // Read program ID from Anchor.toml or IDL metadata
  let programId: PublicKey;

  // Try IDL metadata first
  if (idlRaw.metadata?.address) {
    programId = new PublicKey(idlRaw.metadata.address);
  } else {
    // Fall back to reading from the keypair file
    const keypairPath = path.resolve(
      __dirname, "..", "target", "deploy", "token_sale-keypair.json"
    );
    if (fs.existsSync(keypairPath)) {
      const raw = fs.readFileSync(keypairPath, "utf-8");
      const secretKey = Uint8Array.from(JSON.parse(raw));
      programId = Keypair.fromSecretKey(secretKey).publicKey;
    } else {
      throw new Error(
        "Could not determine program ID. Ensure the program is built " +
        "and deployed, or set metadata.address in the IDL."
      );
    }
  }

  return { idl: idlRaw as Idl, programId };
}

/**
 * Derives the Sale PDA from seeds: ["sale", mint_pubkey].
 */
function deriveSalePda(programId: PublicKey, mint: PublicKey): [PublicKey, number] {
  return PublicKey.findProgramAddressSync(
    [Buffer.from("sale"), mint.toBuffer()],
    programId
  );
}

async function main(): Promise<void> {
  console.log("🚀 Starting sale initialization...\n");

  // 1. Load configuration
  const config = getConfig();
  const connection = getConnection();

  if (!config.mintAddress) {
    throw new Error(
      "MINT_ADDRESS is not set in .env. Run create-token.ts first."
    );
  }

  // 2. Load admin keypair
  console.log(`📂 Loading admin keypair from: ${config.adminKeypairPath}`);
  const admin: Keypair = loadKeypair(config.adminKeypairPath);
  console.log(`👤 Admin public key: ${admin.publicKey.toBase58()}`);

  const balance = await connection.getBalance(admin.publicKey);
  console.log(`💰 Admin balance: ${balance / 1e9} SOL\n`);

  // 3. Load IDL and set up Anchor program
  const { idl, programId } = loadIdl();
  console.log(`📋 Program ID: ${programId.toBase58()}\n`);

  const wallet = new Wallet(admin);
  const provider = new AnchorProvider(connection, wallet, {
    commitment: "confirmed",
    preflightCommitment: "confirmed",
  });
  const program = new Program(idl, programId, provider);

  // 4. Parse mint address
  const mint = new PublicKey(config.mintAddress);
  console.log(`🪙 Mint: ${mint.toBase58()}`);

  // 5. Derive the Sale PDA
  const [salePda, saleBump] = deriveSalePda(programId, mint);
  console.log(`📍 Sale PDA: ${salePda.toBase58()} (bump: ${saleBump})`);

  // 6. Derive the vault ATA (ATA of sale PDA for the mint)
  const vault = getAssociatedTokenAddressSync(mint, salePda, true);
  console.log(`🏦 Vault (Sale PDA ATA): ${vault.toBase58()}`);

  // 7. Get admin's token account
  const adminTokenAccount = getAssociatedTokenAddressSync(mint, admin.publicKey);
  console.log(`👛 Admin token account: ${adminTokenAccount.toBase58()}\n`);

  // 8. Calculate sale parameters
  const allocationBaseUnits = toBaseUnits(config.saleAllocation, config.tokenDecimals);
  const perWalletMaxBaseUnits = toBaseUnits(config.perWalletMaxTokens, config.tokenDecimals);
  const startTs = Math.floor(Date.now() / 1000);
  const endTs = startTs + config.saleDurationSeconds;

  console.log("📊 Sale Parameters:");
  console.log(`   Price:         ${config.priceLamportsPerWholeToken} lamports per whole token`);
  console.log(`   Allocation:    ${config.saleAllocation} tokens (${allocationBaseUnits.toString()} base units)`);
  console.log(`   Per-wallet max: ${config.perWalletMaxTokens} tokens (${perWalletMaxBaseUnits.toString()} base units)`);
  console.log(`   Start:         ${new Date(startTs * 1000).toISOString()}`);
  console.log(`   End:           ${new Date(endTs * 1000).toISOString()}`);
  console.log(`   Duration:      ${config.saleDurationSeconds} seconds\n`);

  // 9. Call initialize_sale instruction
  console.log("📝 Sending initialize_sale transaction...");
  const txSig = await program.methods
    .initializeSale(
      new BN(config.priceLamportsPerWholeToken),  // price_lamports_per_whole_token
      config.tokenDecimals,                        // token_decimals
      new BN(startTs),                             // start_ts
      new BN(endTs),                               // end_ts
      new BN(allocationBaseUnits.toString()),       // allocation (base units)
      new BN(perWalletMaxBaseUnits.toString())      // per_wallet_max (base units)
    )
    .accounts({
      admin: admin.publicKey,
      mint: mint,
      sale: salePda,
      vault: vault,
      adminTokenAccount: adminTokenAccount,
      systemProgram: SystemProgram.programId,
      tokenProgram: TOKEN_PROGRAM_ID,
      associatedTokenProgram: ASSOCIATED_TOKEN_PROGRAM_ID,
      rent: new PublicKey("SysvarRent111111111111111111111111111111111"),
    })
    .signers([admin])
    .rpc();

  await confirmTx(connection, txSig);

  // 10. Print summary
  console.log("\n═══════════════════════════════════════════════════════════");
  console.log("  SALE INITIALIZATION COMPLETE");
  console.log("═══════════════════════════════════════════════════════════");
  console.log(`  Sale PDA:          ${salePda.toBase58()}`);
  console.log(`  Vault:             ${vault.toBase58()}`);
  console.log(`  Mint:              ${mint.toBase58()}`);
  console.log(`  Price:             ${config.priceLamportsPerWholeToken} lamports/token`);
  console.log(`  Allocation:        ${fromBaseUnits(allocationBaseUnits, config.tokenDecimals)} tokens`);
  console.log(`  Per-wallet cap:    ${fromBaseUnits(perWalletMaxBaseUnits, config.tokenDecimals)} tokens`);
  console.log(`  Start:             ${new Date(startTs * 1000).toISOString()}`);
  console.log(`  End:               ${new Date(endTs * 1000).toISOString()}`);
  console.log(`  Transaction:       ${txSig}`);
  console.log("═══════════════════════════════════════════════════════════\n");
}

main().catch((err) => {
  console.error("❌ Error initializing sale:", err);
  process.exit(1);
});

import * as fs from "fs";
import * as path from "path";
import { PublicKey, Keypair } from "@solana/web3.js";
import { TOKEN_PROGRAM_ID, getAssociatedTokenAddressSync } from "@solana/spl-token";
import { Program, AnchorProvider, Wallet, Idl } from "@coral-xyz/anchor";
import { getConfig, loadKeypair, getConnection, confirmTx, fromBaseUnits } from "./helpers";

/**
 * finalize-sale.ts
 *
 * Finalizes a completed token sale by withdrawing any unsold tokens
 * from the sale vault back to the admin's token account.
 *
 * Usage:
 *   npx ts-node scripts/finalize-sale.ts
 *
 * Prerequisites:
 *   - Sale must have ended (current time > end_ts)
 *   - .env file with MINT_ADDRESS set
 *   - Anchor program built and deployed
 */

/**
 * Loads the Anchor IDL from the built program artifacts.
 */
function loadIdl(): { idl: Idl; programId: PublicKey } {
  const possiblePaths = [
    path.resolve(__dirname, "..", "target", "idl", "token_sale.json"),
    path.resolve(__dirname, "..", ".anchor", "idl", "token_sale.json"),
  ];

  let idlPath: string | undefined;
  for (const p of possiblePaths) {
    if (fs.existsSync(p)) {
      idlPath = p;
      break;
    }
  }

  if (!idlPath) {
    throw new Error(
      "IDL file not found. Please build the Anchor program first:\n" +
      "  anchor build\n" +
      `Searched paths:\n  ${possiblePaths.join("\n  ")}`
    );
  }

  console.log(`📄 Loading IDL from: ${idlPath}`);
  const idlRaw = JSON.parse(fs.readFileSync(idlPath, "utf-8"));

  let programId: PublicKey;
  if (idlRaw.metadata?.address) {
    programId = new PublicKey(idlRaw.metadata.address);
  } else {
    const keypairPath = path.resolve(
      __dirname, "..", "target", "deploy", "token_sale-keypair.json"
    );
    if (fs.existsSync(keypairPath)) {
      const raw = fs.readFileSync(keypairPath, "utf-8");
      const secretKey = Uint8Array.from(JSON.parse(raw));
      programId = Keypair.fromSecretKey(secretKey).publicKey;
    } else {
      throw new Error(
        "Could not determine program ID. Ensure the program is built " +
        "and deployed, or set metadata.address in the IDL."
      );
    }
  }

  return { idl: idlRaw as Idl, programId };
}

/**
 * Derives the Sale PDA from seeds: ["sale", mint_pubkey].
 */
function deriveSalePda(programId: PublicKey, mint: PublicKey): [PublicKey, number] {
  return PublicKey.findProgramAddressSync(
    [Buffer.from("sale"), mint.toBuffer()],
    programId
  );
}

async function main(): Promise<void> {
  console.log("🚀 Starting sale finalization...\n");

  // 1. Load configuration
  const config = getConfig();
  const connection = getConnection();

  if (!config.mintAddress) {
    throw new Error(
      "MINT_ADDRESS is not set in .env. Run create-token.ts first."
    );
  }

  // 2. Load admin keypair
  console.log(`📂 Loading admin keypair from: ${config.adminKeypairPath}`);
  const admin: Keypair = loadKeypair(config.adminKeypairPath);
  console.log(`👤 Admin public key: ${admin.publicKey.toBase58()}`);

  const balance = await connection.getBalance(admin.publicKey);
  console.log(`💰 Admin balance: ${balance / 1e9} SOL\n`);

  // 3. Load IDL and set up Anchor program
  const { idl, programId } = loadIdl();
  console.log(`📋 Program ID: ${programId.toBase58()}\n`);

  const wallet = new Wallet(admin);
  const provider = new AnchorProvider(connection, wallet, {
    commitment: "confirmed",
    preflightCommitment: "confirmed",
  });
  const program = new Program(idl, programId, provider);

  // 4. Parse mint address and derive accounts
  const mint = new PublicKey(config.mintAddress);
  const [salePda] = deriveSalePda(programId, mint);
  const vault = getAssociatedTokenAddressSync(mint, salePda, true);
  const adminTokenAccount = getAssociatedTokenAddressSync(mint, admin.publicKey);

  console.log(`🪙 Mint:              ${mint.toBase58()}`);
  console.log(`📍 Sale PDA:          ${salePda.toBase58()}`);
  console.log(`🏦 Vault:             ${vault.toBase58()}`);
  console.log(`👛 Admin ATA:         ${adminTokenAccount.toBase58()}\n`);

  // 5. Fetch sale account data
  console.log("📊 Fetching sale account data...");
  const saleAccount = await program.account.sale.fetch(salePda);

  const endTs = (saleAccount as any).endTs.toNumber();
  const totalSold = BigInt((saleAccount as any).totalSold.toString());
  const allocation = BigInt((saleAccount as any).allocation.toString());
  const nowTs = Math.floor(Date.now() / 1000);

  console.log(`   Allocation:    ${fromBaseUnits(allocation, config.tokenDecimals)} tokens`);
  console.log(`   Total sold:    ${fromBaseUnits(totalSold, config.tokenDecimals)} tokens`);
  console.log(`   End time:      ${new Date(endTs * 1000).toISOString()}`);
  console.log(`   Current time:  ${new Date(nowTs * 1000).toISOString()}`);

  const unsold = allocation - totalSold;
  console.log(`   Unsold:        ${fromBaseUnits(unsold, config.tokenDecimals)} tokens\n`);

  if (nowTs < endTs) {
    const remaining = endTs - nowTs;
    const hours = Math.floor(remaining / 3600);
    const minutes = Math.floor((remaining % 3600) / 60);
